        return ERR_PTR(ret);
    }

    spin_lock_init(&tpg->tpg_lock);
    mutex_lock(&tpg_list_mutex);
    list_add(&tpg->tpg_list, &tpg_global_list);
    mutex_unlock(&tpg_list_mutex);

