struct se_portal_group *create_tpg(struct se_wwn *wwn, struct config_group *group, const char *name) {
    struct se_portal_group *tpg;
    char *endptr;
    unsigned long tpgt;
    int ret;

    if (strncmp(name, "tpgt_", 5) != 0) {
        pr_err("TPG name must start with 'tpgt_'\n");
        return ERR_PTR(-EINVAL);
    }

    tpgt = simple_strtol(name + 5, &endptr, 10);
    if (*endptr != '\0') {
        pr_err("Invalid TPG tag in name: %s\n", name);
        return ERR_PTR(-EINVAL);
    }

    tpg = kzalloc(sizeof(*tpg), GFP_KERNEL);
    if (!tpg) {
        pr_err("Failed to allocate memory for TPG\n");
        return ERR_PTR(-ENOMEM);
    }

    tpg->tpg_wwn = wwn;
    tpg->tpg_group = group;
    tpg->tpg_tag = tpgt;

    mutex_lock(&tpg_mutex);
    ret = core_tpg_register(wwn->wwn_wwn, tpg);
    if (ret < 0) {
        mutex_unlock(&tpg_mutex);
        kfree(tpg);
        return ERR_PTR(ret);
    }

    list_add(&tpg->tpg_list, &tpg_list);
    mutex_unlock(&tpg_mutex);

    return tpg;
}
